param([string]$RepositoryRoot=(Split-Path -Parent (Split-Path -Parent $PSScriptRoot)))
$ErrorActionPreference='Stop'
. (Join-Path $PSScriptRoot '../lib/Stage3StaticAudit.Common.ps1')
$s=[IO.File]::ReadAllText((Join-Path $RepositoryRoot 'tests/fixtures/AICF_AIQuotaCatalogProbe.c'))
$method=Get-AICFMethodBody ([pscustomobject]@{Source=$s;Code=(ConvertTo-AICFCodeText $s)}) AICF_QuotaClientBootstrap
$method=$method.Replace('System.GetTickCount(m_iQuotaClientAt)','Clock.Now-m_iQuotaClientAt').Replace('GetGame()','Env.Game').Replace('ref ','').Replace('.Count()','.Count')
$method=[regex]::Replace($method,'array<([^>]+)> (\w+) = \{\};','List<$1> $2=new List<$1>();')
$method=$method.Replace('array<SCR_SpawnPoint>','List<SCR_SpawnPoint>').Replace('foreach (SCR_BasePlayerLoadout candidate : loadouts)','foreach (SCR_BasePlayerLoadout candidate in loadouts)').Replace('foreach (SCR_SpawnPoint point : points)','foreach (SCR_SpawnPoint point in points)').Replace('SCR_BasePlayerLoadout loadout;','SCR_BasePlayerLoadout loadout=null;').Replace('SCR_SpawnPoint chosen;','SCR_SpawnPoint chosen=null;')
$method=$method.Replace('!points ||','points==null ||')
foreach($t in @('SCR_PlayerFactionAffiliationComponent','SCR_PlayerLoadoutComponent')){$method=$method.Replace('FindComponent('+$t+')','FindComponent(typeof('+$t+'))')}
$code=@'
using System;using System.Collections.Generic;
public class N{public static implicit operator bool(N n){return n!=null;}}
public static class Clock{public static int Now=1;}
public static class Strings{public static bool IsEmpty(this string s){return string.IsNullOrEmpty(s);}public static bool IsEmpty<T>(this List<T> l){return l.Count==0;}}
public class RplId:N{public bool Valid=true;public bool IsValid(){return Valid;}}
public class Actor:N{public SCR_CampaignFaction Faction;}
public class SCR_CampaignFaction:N{public string GetFactionKey(){return "USSR";}public N GetMainBase(){return this;}public static SCR_CampaignFaction Cast(SCR_CampaignFaction f){return f;}}
public class SCR_Faction{public static SCR_CampaignFaction GetEntityFaction(Actor a){return a.Faction;}}
public class AICF_ContentProfile{public static AICF_ContentProfile GetActive(){return new AICF_ContentProfile();}public string GetRuntimeFactionKey(string s){return s;}}
public class SCR_PlayerFactionAffiliationComponent:N{public SCR_CampaignFaction Faction;public int Calls;public SCR_CampaignFaction GetAffiliatedFaction(){return Faction;}public void RequestFaction(SCR_CampaignFaction f){Calls++;Faction=f;}public static SCR_PlayerFactionAffiliationComponent Cast(object o){return o as SCR_PlayerFactionAffiliationComponent;}}
public class SCR_BasePlayerLoadout:N{public string Resource="actual.et";public string GetLoadoutResource(){return Resource;}}
public class SCR_PlayerArsenalLoadout:SCR_BasePlayerLoadout{public static SCR_PlayerArsenalLoadout Cast(SCR_BasePlayerLoadout l){return l as SCR_PlayerArsenalLoadout;}}
public class SCR_PlayerLoadoutComponent:N{public SCR_BasePlayerLoadout Current;public int Calls;public SCR_BasePlayerLoadout GetLoadout(){return Current;}public void RequestLoadout(SCR_BasePlayerLoadout l){Calls++;Current=l;}public static SCR_PlayerLoadoutComponent Cast(object o){return o as SCR_PlayerLoadoutComponent;}}
public class SCR_SpawnPoint:N{public static List<SCR_SpawnPoint> Points;public bool Active=true,Enabled=true;public RplId Rpl=new RplId();public static List<SCR_SpawnPoint> GetSpawnPointsForFaction(string s){return Points;}public bool IsSpawnPointActive(){return Active;}public bool IsSpawnPointEnabled(){return Enabled;}public RplId GetRplId(){return Rpl;}}
public class SCR_SpawnPointSpawnData{public string Prefab;public RplId Rpl;public SCR_SpawnPointSpawnData(string p,RplId r){Prefab=p;Rpl=r;}}
public class SCR_RespawnComponent:N{public int Calls;public SCR_SpawnPointSpawnData Data;public bool RequestSpawn(SCR_SpawnPointSpawnData d){Calls++;Data=d;return true;}public static SCR_RespawnComponent Cast(SCR_RespawnComponent c){return c;}}
public class SCR_PlayerController:N{public int Id=1,Ready;public Actor Actor;public SCR_PlayerFactionAffiliationComponent Faction=new SCR_PlayerFactionAffiliationComponent();public SCR_PlayerLoadoutComponent Loadout=new SCR_PlayerLoadoutComponent();public SCR_RespawnComponent Respawn=new SCR_RespawnComponent();public int GetPlayerId(){return Id;}public Actor GetControlledEntity(){return Actor;}public object FindComponent(Type t){if(t==typeof(SCR_PlayerFactionAffiliationComponent))return Faction;return Loadout;}public SCR_RespawnComponent GetRespawnComponent(){return Respawn;}public void AICF_QuotaCatalogClientReady(){Ready++;}public static SCR_PlayerController Cast(SCR_PlayerController c){return c;}}
public class Loadouts:N{public List<SCR_BasePlayerLoadout> Values=new List<SCR_BasePlayerLoadout>{new SCR_PlayerArsenalLoadout(),new SCR_BasePlayerLoadout()};public void GetPlayerLoadoutsByFaction(SCR_CampaignFaction f,List<SCR_BasePlayerLoadout> a){a.AddRange(Values);}public int GetLoadoutIndex(SCR_BasePlayerLoadout l){return Values.IndexOf(l);}}
public class Factions:N{public SCR_CampaignFaction Faction=new SCR_CampaignFaction();public SCR_CampaignFaction GetFactionByKey(string key){return Faction;}}
public class Queue:N{public int Removes;public void Remove(Action a){Removes++;}}
public class Game:N{public int Closes;public SCR_PlayerController Player=new SCR_PlayerController();public Factions Factions=new Factions();public Loadouts Loadouts=new Loadouts();public Queue Queue=new Queue();public SCR_PlayerController GetPlayerController(){return Player;}public Factions GetFactionManager(){return Factions;}public Loadouts GetLoadoutManager(){return Loadouts;}public Queue GetCallqueue(){return Queue;}public void RequestClose(){Closes++;}}
public static class Env{public static Game Game;}
public class Client{public int m_iQuotaClientAt,m_iQuotaClientPhase;public bool m_bQuotaClientSpawnRequested;public void Print(string s){}public void AICF_QuotaClientBootstrap()BODY}
public static class Cases{public static int Run(){int n=0;Action<bool,string> need=(ok,s)=>{if(!ok)throw new Exception(s);n++;};Env.Game=new Game();Clock.Now=1;SCR_SpawnPoint.Points=new List<SCR_SpawnPoint>{new SCR_SpawnPoint()};var c=new Client();var p=Env.Game.Player;c.AICF_QuotaClientBootstrap();need(p.Faction.Calls==1&&p.Loadout.Calls==0&&p.Respawn.Calls==0,"phase1");c.AICF_QuotaClientBootstrap();need(p.Loadout.Calls==1&&p.Loadout.Current==Env.Game.Loadouts.Values[1]&&p.Respawn.Calls==0,"phase2_nonarsenal");c.AICF_QuotaClientBootstrap();need(p.Respawn.Calls==1&&p.Respawn.Data.Prefab=="actual.et"&&p.Respawn.Data.Rpl.Valid,"phase3_valid_native_inputs");c.AICF_QuotaClientBootstrap();need(p.Respawn.Calls==1,"no_duplicate_spawn");p.Actor=new Actor{Faction=Env.Game.Factions.Faction};c.AICF_QuotaClientBootstrap();need(p.Ready==1&&Env.Game.Queue.Removes==1,"phase4_actual_actor");foreach(string bad in new[]{"empty_points","inactive","disabled","rpl","empty_prefab","no_loadouts","no_playerid"}){Env.Game=new Game();p=Env.Game.Player;p.Faction.Faction=Env.Game.Factions.Faction;p.Loadout.Current=Env.Game.Loadouts.Values[1];SCR_SpawnPoint.Points=new List<SCR_SpawnPoint>{new SCR_SpawnPoint()};switch(bad){case"empty_points":SCR_SpawnPoint.Points.Clear();break;case"inactive":SCR_SpawnPoint.Points[0].Active=false;break;case"disabled":SCR_SpawnPoint.Points[0].Enabled=false;break;case"rpl":SCR_SpawnPoint.Points[0].Rpl.Valid=false;break;case"empty_prefab":p.Loadout.Current.Resource="";break;case"no_loadouts":Env.Game.Loadouts.Values.Clear();break;case"no_playerid":p.Id=0;break;}c=new Client();c.AICF_QuotaClientBootstrap();need(p.Respawn.Calls==0,"veto_"+bad);}Env.Game=new Game();c=new Client();Clock.Now=240000;c.AICF_QuotaClientBootstrap();need(Env.Game.Closes==1&&Env.Game.Queue.Removes==1,"bounded_timeout");return n;}}
'@
$code=$code.Replace('BODY',$method)
Add-Type $code;$actual=[Cases]::Run();$unsafe=0
foreach($m in @(@('repeatspawn','if (m_bQuotaClientSpawnRequested) return;',''),@('invalidrpl','&& point.GetRplId().IsValid()',''),@('disabled','&& point.IsSpawnPointEnabled()',''))){if(!$code.Contains($m[1])){throw "Missing bootstrap mutation $($m[0])"};$ns='UnsafeBootstrap'+$m[0];Add-Type ('namespace '+$ns+' {'+$code.Replace($m[1],$m[2])+'}');$rejected=$false;try{$null=([type]($ns+'.Cases')).GetMethod('Run').Invoke($null,@())}catch{$rejected=$true};if(!$rejected){throw "Unsafe bootstrap survived $($m[0])"};$unsafe++}
"PASS catalog actual_client_bootstrap_cases=$actual executed_unsafe=$unsafe native_runtime=NOT_RUN"
